describe("cart", () => {
  let cart;

  beforeEach(() => {
    cart = createCart();
  });

  it("starts empty", () => {
    expect(cart.items).toHaveLength(0);
  });

  it("adds an item", () => {
    cart.add({ id: "a1", price: 10 });

    expect(cart.items).toHaveLength(1);
    expect(cart.total()).toBe(10);
  });
});

